mapper.select:
select pt.id as taskId, pt.task_name, pt.user_id, su.user_wx_name, pt.project_id, pt.close_time from pmhub_project_task pt join pmhub_project p on p.id = pt.project_id left join sys_user su on su.user_id = pt.user_id where p.deleted = 0 and p.msg_notify = 1 and p.status != #{pauseStatus} and pt.deleted = 0 and pt.close_time is not null and pt.status != #{finishedStatus}
and DATEDIFF(pt.close_time, CURDATE()) = p.notify_day
and not exists( select 1 from pmhub_project_task_notify n where n.task_id = pt.id and n.close_time = pt.close_time and n.overdue = 0 )
